<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Spin Doorprize Display</title>@vite(['resources/css/app.css','resources/js/app.js'])</head><body class="min-h-screen bg-white text-slate-800" x-data="display()" @keydown.window="if($event.key==='Enter'&&!busy&&state==='siap')trigger()"><main class="flex min-h-screen flex-col items-center justify-center p-8 text-center"><p class="text-xs font-bold uppercase tracking-[.35em] text-emerald-600">Layar Doorprize</p><h1 class="mt-4 text-5xl font-extrabold" x-text="event.name || 'Spin Doorprize'"></h1>

<template x-if="state==='idle'"><div class="mt-16"><div class="mx-auto flex h-24 w-24 items-center justify-center rounded-3xl bg-emerald-50 text-5xl">🎁</div><p class="mt-8 text-2xl text-slate-400">Menunggu hadiah dipilih oleh operator...</p></div></template>

<template x-if="state==='siap'"><div class="mt-12"><p class="text-lg font-bold uppercase tracking-[.3em] text-emerald-600">Siap Diundi</p><template x-if="spin.prize_image"><img :src="spin.prize_image" class="mx-auto mt-6 h-48 w-48 rounded-3xl border-4 border-emerald-500 object-cover shadow-2xl"></template><h2 class="mt-5 text-5xl font-extrabold tracking-tight" x-text="spin.prize_name"></h2><p class="mt-3 text-xl text-slate-500" x-text="spin.mode==='utama' ? 'Hadiah Utama' : 'Hadiah Massal'"></p><template x-if="spin.mode==='utama'"><div class="mt-8 flex items-center justify-center gap-3"><span class="mr-2 text-5xl font-black text-emerald-600">AST</span><template x-for="i in 4"><div class="flex h-28 w-20 items-center justify-center rounded-2xl border-4 border-emerald-500 bg-emerald-50 font-mono text-6xl font-black text-emerald-600 shadow-xl">?</div></template></div></template><button @click="trigger()" :disabled="busy" class="mt-10 rounded-3xl bg-[#089850] px-16 py-6 text-3xl font-black text-white shadow-2xl shadow-emerald-200 transition hover:bg-[#007a42] active:scale-95 disabled:opacity-50">SPIN</button><p class="mt-5 text-sm text-slate-400">atau tekan tombol ENTER pada keyboard</p></div></template>

<template x-if="state==='berjalan' && spin.mode==='utama'"><div class="mt-10 flex flex-col items-center"><p class="text-xl font-semibold text-emerald-600" x-text="spin.prize_name"></p><template x-if="spin.prize_image"><img :src="spin.prize_image" class="mx-auto mt-5 h-32 w-32 rounded-2xl object-cover shadow-xl"></template><p class="mt-6 text-sm font-bold uppercase tracking-[.3em] text-slate-400">Nomor pemenang</p><div class="mt-5 flex items-center justify-center gap-3"><span class="mr-2 text-5xl font-black text-emerald-600">AST</span><template x-for="(digit,i) in reels" :key="i"><div class="relative flex h-36 w-24 items-center justify-center overflow-hidden rounded-2xl border-4 shadow-2xl transition-all duration-300" :class="stopped[i] ? 'border-amber-400 bg-amber-50 scale-105' : 'border-emerald-500 bg-emerald-50'"><span class="font-mono text-7xl font-black" :class="stopped[i] ? 'text-amber-600' : 'text-emerald-600 blur-[1px]'" x-text="digit"></span><div x-show="!stopped[i]" class="absolute inset-x-0 top-1/2 h-px bg-emerald-300"></div></div></template></div><p class="mt-8 text-xl font-semibold text-slate-400" x-text="reelsDone ? 'Pemenang terpilih!' : 'Mengundi...'"></p></div></template>

<template x-if="state==='berjalan' && spin.mode==='massal'"><div class="mt-8 w-full max-w-[97vw]"><div class="flex items-center justify-center gap-4"><template x-if="spin.prize_image"><img :src="spin.prize_image" class="h-16 w-16 rounded-2xl border-2 border-emerald-500 object-cover shadow-lg"></template><h2 class="text-3xl font-extrabold uppercase tracking-[.25em] text-emerald-600">HADIAH PEMENANG</h2><span class="text-2xl font-extrabold text-slate-700" x-text="spin.prize_name"></span></div><p class="mt-2 text-sm font-bold uppercase tracking-[.3em] text-slate-400">Pengundian berlangsung</p><div class="mt-5 grid justify-center" :style="gridStyle"><template x-for="(cell,i) in massalCells" :key="i"><div class="flex items-center justify-center rounded-xl border-2 bg-emerald-50 font-mono font-black text-emerald-600 shadow" :class="state==='berjalan' ? 'border-emerald-500' : 'border-amber-400 bg-amber-50 text-amber-600'" :style="cellStyle" x-text="cell"></div></template></div></div></template>

<template x-if="state==='selesai' && spin.mode==='utama'"><div class="mt-12 w-full max-w-6xl"><canvas x-ref="fireworks" class="pointer-events-none fixed inset-0 z-50 h-full w-full"></canvas><div class="flex items-center justify-center gap-3"><span class="mr-2 text-5xl font-black text-emerald-600">AST</span><template x-for="(digit,i) in reels" :key="i"><div class="flex h-36 w-24 items-center justify-center rounded-2xl border-4 border-amber-400 bg-amber-50 font-mono text-7xl font-black text-amber-600 shadow-2xl scale-105" x-text="digit"></div></template></div><p class="mt-6 text-3xl font-extrabold text-emerald-600">🎉 Selamat kepada seluruh pemenang!</p><p class="mt-3 text-xl font-semibold text-slate-700">Anda memenangkan hadiah doorprize <span x-text="spin.prize_name"></span></p><template x-if="spin.prize_image"><img :src="spin.prize_image" class="mx-auto mt-6 h-48 w-48 rounded-3xl border-4 border-emerald-500 object-cover shadow-xl"></template><div class="mt-8 grid gap-4" :class="spin.winners.length > 8 ? 'grid-cols-2 md:grid-cols-5' : (spin.winners.length > 2 ? 'grid-cols-2 md:grid-cols-3' : 'grid-cols-1')"><template x-for="winner in shown" :key="winner.code"><div class="rounded-3xl border-4 border-emerald-500 bg-emerald-50 p-8 shadow-xl"><p class="text-3xl font-black text-emerald-600" x-text="winner.name"></p><p class="mt-4 text-xl text-slate-500" x-text="winner.nik"></p><p class="mt-1 text-sm font-medium text-slate-500" x-text="winner.department"></p></div></template></div></div></template>

<template x-if="state==='selesai' && spin.mode==='massal'"><div class="mt-8 w-full max-w-[97vw]"><canvas x-ref="fireworks" class="pointer-events-none fixed inset-0 z-50 h-full w-full"></canvas><div class="flex items-center justify-center gap-4"><template x-if="spin.prize_image"><img :src="spin.prize_image" class="h-16 w-16 rounded-2xl border-2 border-emerald-500 object-cover shadow-lg"></template><h2 class="text-3xl font-extrabold uppercase tracking-[.25em] text-emerald-600">HADIAH PEMENANG</h2><span class="text-2xl font-extrabold text-slate-700" x-text="spin.prize_name"></span></div><p class="mt-2 text-lg font-extrabold text-emerald-600">Selamat kepada seluruh pemenang!</p><div class="mt-4 grid justify-center" :style="gridStyle"><template x-for="(cell,i) in massalCells" :key="i"><div class="flex items-center justify-center rounded-xl border-2 border-amber-400 bg-amber-50 font-mono font-black text-amber-600 shadow" :style="cellStyle" x-text="cell"></div></template></div></div></template>

</main>
<script>function display(){return{event:{},spin:null,state:'idle',shown:[],busy:false,lastId:null,lastStatus:null,reels:['0','0','0','0'],stopped:[false,false,false,false],reelsDone:false,reelTimers:[],massalCells:[],massalTimer:null,massalTimers:[],get massalCount(){return Math.max(1,this.spin?.winner_count||this.spin?.winners?.length||1)},get cols(){const n=this.massalCount;return n<=30?6:n<=80?10:15},get gridStyle(){const n=this.massalCount;return `grid-template-columns:repeat(${this.cols},minmax(0,1fr));gap:${n>80?'.4rem':'.6rem'}`},get cellStyle(){const n=this.massalCount;const font=n<=30?'clamp(.9rem,2.2vw,1.6rem)':n<=80?'clamp(.7rem,1.6vw,1.15rem)':'clamp(.55rem,1.2vw,.9rem)';const pad=n<=30?'.9rem':n<=80?'.5rem':'.3rem';return `font-size:${font};padding:${pad} ${pad}`},randomCode(){const pool=(this.spin?.codes||[]).filter(c=>/^\d+$/.test(c));return pool.length?'AST'+pool[Math.floor(Math.random()*pool.length)]:'AST'+String(Math.floor(Math.random()*10000)).padStart(4,'0')},startMassalShuffle(){this.stopMassalShuffle();this.massalCells=Array.from({length:this.massalCount},()=>this.randomCode());this.massalTimer=setInterval(()=>{this.massalCells=this.massalCells.map(()=>this.randomCode())},90);this.massalTimers.push(setTimeout(()=>{this.stopMassalShuffle();this.massalCells=this.spin.winners.map(w=>w.code)},10000))},stopMassalShuffle(){this.massalTimers.forEach(t=>clearTimeout(t));this.massalTimers=[];if(this.massalTimer){clearInterval(this.massalTimer);this.massalTimer=null}},async load(){const d=await fetch("{{ url('display/'.$token) }}/state").then(r=>r.json());this.event=d.event||{};this.spin=d.spin||null;const nextState=this.spin?this.spin.status:'idle';const changedSpin=this.spin&&this.spin.id!==this.lastId;const changedStatus=nextState!==this.lastStatus;this.state=nextState;if(this.spin&&changedStatus)this.lastStatus=nextState;if(!this.spin)return;if(this.state==='siap'&&changedSpin){this.lastId=this.spin.id;this.lastStatus='siap';this.busy=false;this.shown=[];this.massalCells=[];this.stopReels();this.stopMassalShuffle()}if(this.state==='berjalan'&&changedStatus){this.lastId=this.spin.id;if(this.spin.mode==='utama')this.$nextTick(()=>this.startReels(this.spin.winners[0]?.code,this.spin.spin_duration,this.spin.last_digit_duration));else this.startMassalShuffle()}if(this.state==='selesai'&&(changedSpin||changedStatus)){this.lastId=this.spin.id;this.stopReels();this.stopMassalShuffle();if(this.spin.mode==='utama'){const t=(this.spin.winners[0]?.code||'AST0000').replace(/^AST/,'').padStart(4,'0').slice(-4).split('');this.reels=t;this.stopped=[true,true,true,true];this.reelsDone=true;this.shown=this.spin.winners}else{this.massalCells=this.spin.winners.map(w=>w.code)}await this.$nextTick();this.startFireworks()}if(this.state!=='selesai')this.stopFireworks()},async trigger(){if(this.busy||this.state!=='siap')return;this.busy=true;try{await fetch("{{ url('display/'.$token) }}/trigger/"+this.spin.id,{method:'POST',headers:{'X-CSRF-TOKEN':'{{ csrf_token() }}'}})}catch(e){this.busy=false}},startReels(code,duration,lastDuration){this.stopReels();this.reels=['0','0','0','0'];this.stopped=[false,false,false,false];this.reelsDone=false;const target=(code||'AST0000').replace(/^AST/,'').padStart(4,'0').slice(-4).split('');const d=(duration||10)*1000,last=(lastDuration||5)*1000;for(let i=0;i<4;i++){this.reelTimers.push(setInterval(()=>{this.reels[i]=String(Math.floor(Math.random()*10));this.reels=[...this.reels]},65+i*12));const stopAt=i<3?(i+1)*d:3*d+last;this.reelTimers.push(setTimeout(()=>{clearInterval(this.reelTimers[i*2]);this.reels[i]=target[i];this.reels=[...this.reels];this.stopped[i]=true;this.stopped=[...this.stopped];if(i===3)this.reelsDone=true},stopAt))}},stopReels(){this.reelTimers.forEach(t=>{clearInterval(t);clearTimeout(t)});this.reelTimers=[]},startFireworks(){this.stopFireworks();const canvas=this.$refs.fireworks;if(!canvas)return;canvas.width=innerWidth;canvas.height=innerHeight;const ctx=canvas.getContext('2d');const colors=['#089850','#fbbf24','#34d399','#f59e0b','#86efac','#fde68a'];let rockets=[],particles=[],raf=null,launch=null;const boom=(x,y)=>{const c=colors[Math.floor(Math.random()*colors.length)];for(let i=0;i<70;i++){const a=Math.random()*2*Math.PI,s=Math.random()*5+2;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:1,color:Math.random()<.75?c:colors[Math.floor(Math.random()*colors.length)]})}};const tick=()=>{ctx.clearRect(0,0,canvas.width,canvas.height);rockets=rockets.filter(r=>{r.y+=r.vy;r.vy+=.12;r.x+=r.vx;ctx.fillStyle='rgba(8,152,80,.9)';ctx.fillRect(r.x-2,r.y-8,4,10);if(r.vy>=-1){boom(r.x,r.y);return false}return true});particles=particles.filter(p=>{p.x+=p.vx;p.y+=p.vy;p.vx*=.985;p.life-=.012;if(p.life<=0)return false;ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,2.4,0,2*Math.PI);ctx.fill();ctx.globalAlpha=1;return true});raf=requestAnimationFrame(tick)};const spawn=()=>{rockets.push({x:canvas.width*(0.15+Math.random()*0.7),y:canvas.height+10,vx:(Math.random()-.5)*2,vy:-(9+Math.random()*4)})};spawn();spawn();launch=setInterval(spawn,850);raf=requestAnimationFrame(tick);this._fw={raf,launch}},stopFireworks(){if(this._fw){cancelAnimationFrame(this._fw.raf);clearInterval(this._fw.launch);this._fw=null;this.$refs.fireworks?.getContext('2d')?.clearRect(0,0,innerWidth,innerHeight)}},init(){this.load();setInterval(()=>this.load(),1500)}}}</script></body></html>
